    "test:types": "node ../scripts/generate-package-versions.mjs && vitest --typecheck.only --run",
    "type-check:breaking": "tsc -p tsconfig.types-bundler.json && tsc -p tsconfig.types-public-package.json",
    "size": "size-limit",
    "prepublishOnly": "npm run sync && npm run type-check && npm test && npm run clean && npm run build && npm run build:smoke && node ../scripts/pack-consumer-smoke.mjs --package=wrapper"
  },
  "overrides": {
    "typed-rest-client": {
      "qs": "6.15.3"
    }
  },
  "devDependencies": {
    "@size-limit/file": "^12.1.0",
    "@types/node": "^22",
    "@vitest/coverage-v8": "^4.1.10",
    "eslint": "^10.8.0",
    "eslint-plugin-import-x": "^4.17.1",
    "fast-check": "^4.9.0",
    "prettier": "^3.9.5",
    "size-limit": "^12.1.0",
    "tsx": "^4.23.1",
    "typedoc": "^0.28.20",
    "typescript": "^7.0.2",
    "typescript-eslint": "^8.65.0",
    "vitest": "^4.1.10"
  }
}
